var a={copy:t=>JSON.parse(JSON.stringify(t)),getToday:(t=0)=>{let n=new Date;n.setDate(n.getDate()-t);let r=n.getFullYear(),e=String(n.getMonth()+1).padStart(2,"0"),i=String(n.getDate()).padStart(2,"0");return`${r}-${e}-${i}`},date:(t=new Date,n="YYMMDDHHMM")=>{let r=t.getFullYear(),e=String(t.getMonth()+1).padStart(2,"0"),i=String(t.getDate()).padStart(2,"0"),s=String(t.getHours()).padStart(2,"0"),o=String(t.getMinutes()).padStart(2,"0");return n=="YYMMDD"?`${r}-${e}-${i}`:`${r}-${e}-${i} ${s}:${o}`},dateStr:(t=new Date,n="YYMMDDHHMM")=>{let r=t.getFullYear(),e=String(t.getMonth()+1).padStart(2,"0"),i=String(t.getDate()).padStart(2,"0"),s=String(t.getHours()).padStart(2,"0"),o=String(t.getMinutes()).padStart(2,"0");return n=="YYMMDD"?`${r}_${e}_${i}`:`${r}_${e}_${i}_${s}_${o}`},formatDate:t=>t?t.split(" ").length>1?t.split(" ")[0].split("/").reverse().join("-"):t.split("/").reverse().join("-"):"",capitalize:t=>t?t.charAt(0).toUpperCase()+t.slice(1).toLowerCase():"",capitalizeWords:t=>t?t.split(" ").map(n=>a.capitalize(n)).join(" "):"",sort:(t,n,r)=>{t.sort((e,i)=>{let s=a.copy(e)[r],o=a.copy(i)[r];return isNaN(s)?n==="down"?s.localeCompare(o):o.localeCompare(s):n==="down"?s-o:o-s})}};export{a};
